sharedComponents.component("mixDatabaseFormWeb", {
  templateUrl:
    "/mix-app/views/app-shared/components/mix-db-data-form-web/view.html",
  bindings: {
    mixDbTableId: "=",
    mixDbTableName: "=",
    mixDbDataId: "=?",
    mixDbData: "=?",
    parentType: "=?",
    parentId: "=?",
    defaultId: "=",
    saveData: "&?",
  },
  controller: [
    "$rootScope",
    "$scope",
    "RestMixDbTablePortalService",
    function ($rootScope, $scope, service) {
      var ctrl = this;
      ctrl.isBusy = false;
      ctrl.attributes = [];
      ctrl.defaultData = null;
      ctrl.selectedProp = null;
      ctrl.mixConfigurations = $rootScope.globalSettings;
      ctrl.$onInit = async function () {
        ctrl.defaultData = await service.getSingle("web", [
          ctrl.defaultId,
          ctrl.mixDbTableId,
          ctrl.mixDbTableName,
        ]);
        ctrl.loadData();
      };
      ctrl.loadData = async function () {
        /*
                    If input is data id => load ctrl.mixDbData from service and handle it independently
                    Else modify input ctrl.mixDbData
                */
        $rootScope.isBusy = true;
        if (ctrl.mixDbDataId) {
          ctrl.mixDbData = await service.getSingle("portal", [
            ctrl.mixDbDataId,
            ctrl.mixDbTableId,
            ctrl.mixDbTableName,
          ]);
          if (ctrl.mixDbData) {
            ctrl.defaultData.mixDbTableId = ctrl.mixDbData.mixDbTableId;
            ctrl.defaultData.mixDbTableName = ctrl.mixDbData.mixDbTableName;
            $rootScope.isBusy = false;
            $scope.$apply();
          } else {
            if (ctrl.mixDbData) {
              $rootScope.showErrors("Failed");
            }
            $rootScope.isBusy = false;
            $scope.$apply();
          }
        } else {
          if (!ctrl.mixDbData) {
            ctrl.mixDbData = angular.copy(ctrl.defaultData);
          }
          $rootScope.isBusy = false;
          $scope.$apply();
        }
      };
      ctrl.reload = async function () {
        ctrl.mixDbData = angular.copy(ctrl.defaultData);
      };
      ctrl.submit = async function () {
        angular.forEach(ctrl.mixDbData.values, function (e) {
          //Encrypt column before send
          if (e.column.isEncrypt) {
            var encryptData = $rootScope.encrypt(e.stringValue);
            e.encryptKey = encryptData.key;
            e.encryptValue = encryptData.data;
            e.stringValue = null;
          }
        });
        if (ctrl.saveData) {
          ctrl.isBusy = true;
          var result = await ctrl.saveData({ data: ctrl.mixDbData });
          if (result && result.success) {
            ctrl.isBusy = false;
            ctrl.mixDbData = result.data;
            $scope.$apply();
          } else {
            ctrl.isBusy = false;
            // ctrl.mixDbData = await service.getSingle('portal', [ctrl.defaultId, ctrl.mixDbTableId, ctrl.mixDbTableName]);
            $scope.$apply();
          }
        } else {
          ctrl.isBusy = true;
          var saveResult = await service.save(ctrl.mixDbData);
          if (saveResult.success) {
            ctrl.isBusy = false;
          } else {
            ctrl.isBusy = false;
            if (saveResult) {
              $rootScope.showErrors(saveResult.errors);
            }
            $scope.$apply();
          }
        }
      };

      ctrl.filterData = function (attributeName) {
        if (ctrl.mixDbData) {
          var attr = $rootScope.findObjectByKey(
            ctrl.mixDbData.data,
            "mixDatabaseColumnName",
            attributeName
          );
          if (!attr) {
            attr = angular.copy(
              $rootScope.findObjectByKey(
                ctrl.defaultData.data,
                "mixDatabaseColumnName",
                attributeName
              )
            );
            ctrl.mixDbData.data.push(attr);
          }
          return attr;
        }
      };
    },
  ],
});

